CREATE TABLE `tb_lifetech_syntax_library` (
  `lifetech_general_id` bigint(15) NOT NULL,
  `lifetech_table_status` int(3) DEFAULT NULL,
  `syntax_name` varchar(100) DEFAULT NULL,
