INSERT INTO `tb_lifetech_syntax_library` (`lifetech_general_id`, `lifetech_table_status`, `syntax_name`, `syntax_value`, `syntax_category`, `created_at`, `updated_at`) VALUES
(120, 1, 'Session GET', '//this is to load a session varriable\r\nSession::get($ses_name);', 'Session_class', NULL, '2024-11-28 13:15:42'),
(122, 1, 'load_content_data', 'if($_GET[\'load_content_data\'] == \'#Enter Your Content Name#\'  ){\nob_end_clean();\n $response_load_content = jlon_create($response_load_content); \n$response_load_content -> echo_type_div= \"Yes\";\n//$response_load_content -> echo_type_modal= \"Yes\";\n//$response_load_content -> content_form .= \"#Enter Your Form Parameter#\";\n//$response_load_content -> content_header .= \"#Enter Your Content Header#\";\n$response_load_content -> content_body .= \"#Enter Your Content Body#\";\n//$response_load_content -> content_footer .= \"#Enter Your Content footer#\";\n//$response_load_content -> content_jquery .= \"#Enter Your Jquery parameter#\";\necho jlon_encode($response_load_content);\nexit();\n\n}\n\necho load_content_data(\'content_name=#Your Content Name#, onload=yes\');', 'content_data', NULL, '2024-10-26 11:07:36'),
(233, 1, 'post_content_data', 'if ($_POST[\'post_content_data\']  == \'#Enter Your Element ID#\'){\n    ob_end_clean();  \n$response_post_content = jlon_create($response_post_content); \n$response_post_content -> content_body .=\'#Enter the body to display#\' ;\n $response_post_content ->echo_type_modal =\'Yes\';\n//$response_post_content ->reload_content_data =\'#Enter the Content Name to Reload#\';\n  \necho jlon_encode($response_post_content);\nexit();\n} ', 'content_data', NULL, '2024-10-26 11:07:36'),
(256, 1, 'edit_content_data', 'if($_GET[\"edit_content_data\"] == \'#Enter Your Content Name#\'){\n    ob_end_clean();\n$check_url = validate_url();\nif ($check_url  == \'success\'){ \n//this is where u put the code\n\n $response_edit_content = jlon_create($response_edit_content); \n$response_edit_content -> content_header =\'Edit Your Form Object\';\n \n$response_edit_content -> content_body .= $lifetech_modal_body;\n$response_edit_content -> content_footer .= $lifetech_modal_footer;\n$response_edit_content -> content_jquery .= $lifetech_modal_jquery ;\n$response_edit_content -> echo_type_modal .= \"Yes\";\necho jlon_encode($response_edit_content);\n    exit();\n\n    }else{ \n\n$response_edit_content = jlon_create($response_edit_content);\n$response_edit_content -> content_body .= \'Your Id is not equivalent to your Pin  \'; \necho jlon_encode($response_edit_content); \nexit();\n\n\n}\n}', 'content_data', NULL, '2024-10-26 11:07:36'),
(309, 1, 'Session SET', '//this is used to set a session varriable\r\n\r\nSession::set($key, $value);', 'Session_class', NULL, '2024-11-28 13:44:48'),
(338, 1, 'Session Destroy', '//this is to destroy all session on your application, especially when you logout\r\n\r\nSession::destroy();', 'Session_class', NULL, '2024-11-28 13:53:49'),
(341, 1, 'Session Forget', '//this is used to forget or unset a particular session varriable\r\nSession::forget($ses_name);', 'Session_class', NULL, '2024-11-28 13:51:28'),
(342, 1, 'lifetech_obj_html_element_loader', '\n\n$get_element = \"\'name=#The element Name#\',  \'type=text\',  \'value=#the value#\',  \'label =#the caption to display#\'\"; 		\n  echo lifetech_obj_html_element_loader($get_element);\n', 'Lifefunction', NULL, '2024-10-26 11:07:36'),
(357, 1, 'Session All', '//this will load all sessions in an array for you\r\nSession::all();', 'Session_class', NULL, '2024-11-28 13:44:48'),
(384, 1, 'Session HAS', '//this is used to determine if a session is set or available, which returns true or false\r\nif(Session::has($ses_name)){\r\n //write your code here;\r\n}\r\n', 'Session_class', NULL, '2024-11-28 13:51:28'),
(432, 1, 'lifetech_obj_jquery_form_post', '\n$paramerts_get = \"\'form_id = #Your Form Id#\',  \'element_id =#Enter Action Id#\', \'event=#your event#\', \'loader=Yes\'\";  \n$lifetech_modal_jquery .= lifetech_obj_jquery_form_post($paramerts_get);', 'Lifefunction', NULL, '2024-10-26 11:07:36'),
(434, 1, 'lifetech_obj_html_table_view', 'echo  \'<table  id=\"example\" class=\"table table-striped table-bordered \">\';\n$loadtable = getLifetechClass();\n$loadtable -> table_name = \'#Enter Table name#\';  $loadtable -> content_name = \'#enter content name#\';\n$loadtable -> table_header = \'sno, level names, Date, Edit, Delete, Status Value, static value\';\n$loadtable -> table_fieldname = \'_sn,lifetech_add_level,lifetech_date, _edit:lifetech_general_id:, _delete:lifetech_general_id:remove,_status:lifetech_table_status, _static:Inactive\';\n$table_response = $loadtable -> lifetech_obj_html_table_view();\necho $table_response;\necho \'</table>\';', 'Lifefunction', NULL, '2024-10-26 11:07:36'),
(437, 1, 'lifetech_obj_db_insert', '    $lifetech_general_id =  lifetech_general_id();    \n    $formInputs_insert = getLifetechClass();\n    $formInputs_insert -> table_name = \'#Enter table name#\';\n    $formInputs_insert -> table_record_exist = \'lifetech_category_name and lifetech_school_id\';\n    $formInputs_insert -> element_empty = \'#enter element id#\';\n    $formInputs_insert -> echo_type_div= \'Yes\';  \n    $formInputs_insert -> table_fieldvalue = \'lifetech_category_name, _lifetech_school_id, _lifetech_general_id, _lifetech_date\';\n    //$formInputs_insert -> form_reset= \'Yes\';\n    //$formInputs_insert -> echo_type_alert= \'Yes\'; \n    //$formInputs_insert ->element_empty_response=\'#Customize Response when element is Empty#\';\n    //$formInputs_insert ->table_record_exist_response=\'#Customize Response when Record already Exist#\';\n    //$formInputs_insert -> use_registration_table= \'Yes\';\n\n    $response_insert_obj =  $formInputs_insert -> lifetech_obj_db_insert();\n    echo $response_insert_obj ;\n    exit();\n    \n    /* if you want to check whether the data has inserted and to perform another operations aftermath\n        then u need to decode the insert status to check whether it is 0 or 1\n            $response_insert_obj_decode = jlon_decode($response_insert_obj);\n            if($response_insert_obj_decode-> display_insert_status == \'0\' ){\n                //meaning the data did not Insert\n            }else{\n                //the data inserted, then perform additional operation u want to\n            }\n    */', 'Lifefunction', NULL, '2024-10-26 11:07:36'),
(443, 1, 'RESPONSE Class', '//this used to create a response back to the frontend dev in json format\r\n//response_category is categorized into two 100 for fail, 200 for success\r\n//response_data is optional and is for when when you want to return records to the frontend\r\n\r\n$response = Response::json($response_result=\"registration successful\", $response_code=\"201\", $response_category=\"200\",$response_data=$data);', 'Request_and_Response', NULL, '2024-11-28 14:13:09'),
(485, 1, 'REQUEST Class', '//this is used to load the requested data from the users\r\n\r\n<?php\r\n   $request = new Request;\r\n      $userName = $request->username;\r\n      $passWord =    $request->password;\r\n?>\r\n', 'Request_and_Response', NULL, '2024-11-28 14:13:09'),
(517, 1, 'lifetech_obj_db_update', '$parameter_update_obj = \"\'table_name=#Enter Table name#\', \'table_where=#specify conditons#\', \'table_fieldvalue=#enter field value#\' \";\n$response_update_obj= lifetech_obj_db_update($parameter_update_obj);\necho $response_update_obj -> display_update_result;', 'Lifefunction', NULL, '2024-10-26 11:07:36'),
(521, 1, 'lifetech_obj_db_select', '$urid = \'4\';\n$parameter_select_obj = \"\'table_name = user_role\' ,  \'table_fieldname =urid\', \'table_where =_urid\', \'#*table_order=ORDER BY sn\', \'#*table_limit= LIMIT 10\'\";\n$response_select_obj = lifetech_obj_db_select($parameter_select_obj); \n if ($response_select_obj -> rowCount() > 0 ) {\n    while ($load_select_obj = $response_select_obj -> fetch() ){\n       echo $load_select_obj ->urid; //take note, it is those fields inside your table_fieldname that u can echo \n    }\n}\n', 'Lifefunction', NULL, '2024-10-26 11:07:36'),
(549, 1, 'lifetech_db_delete', '$delete_table_name=\"#Name of the table#\"; $delete_table_where=\"table_field_name =\'table_record_value\'\";\n    $delete_records_feedback = lifetech_db_delete($delete_table_name, $delete_table_where);\n      if ($delete_records_feedback[\'response\']=\'success\'){\n         //Record Deleted \n       }else{\n         $delete_error_encountered =$delete_records_feedback[\'results\']; \n         //display the error\n       }', 'Lifefunction', NULL, '2024-10-26 11:07:36'),
(601, 1, 'lifetech_obj_db_create', '$lifech_create_obj = getLifetechClass();\r\n$lifech_create_obj -> table_name =\'#Enter the table name#\';\r\n$lifech_create_obj -> table_fieldname =\"success_reponse, already_exist, element_empty, lifetech_general_id, lifetech_status\";\r\n$lifech_create_obj -> table_fieldtype =\"varchar , text, text, bigint, varchar\";\r\n$lifech_create_obj -> table_fieldlength =\"120 , 80, 80, 15,2\";                   \r\n$lifech_create_obj_feedback = $lifech_create_obj -> lifetech_obj_db_create();\r\necho $lifech_create_obj_feedback;', 'Lifefunction', NULL, '2024-10-26 11:07:36'),
(623, 1, 'lifetech_obj_db_alter', '\r\n$lifech_alter_obj = getLifetechClass();\r\n$lifech_alter_obj -> table_name =\'#Enter the table name#\'; \r\n$lifech_alter_obj -> table_fieldname =\"lifetech_questions\";\r\n$lifech_alter_obj -> table_fieldtype =\"varchar\";\r\n$lifech_alter_obj -> table_fieldlength =\"120\"; \r\n$lifech_alter_obj -> table_altertype =\"ADD\"; //   $lifech_alter_obj -> table_altertype =\"CHANGE\"; if u want to edit the field name\r\n$lifech_alter_obj_feedback = $lifech_alter_obj -> lifetech_obj_db_alter();\r\necho $lifech_alter_obj_feedback;', 'Lifefunction', NULL, '2024-10-26 11:07:36'),
(640, 1, 'lifetech_obj_getone_record', '\r\n$urid=\'2\';\r\n$parameter_getone = \"\'table_name=#enter your table name#\', \'table_where=_urid\'\";\r\n$response_obj_getone= lifetech_obj_getone_record($parameter_getone);\r\necho $response_obj_getone ->roles;\r\n', 'Lifefunction', NULL, '2024-10-26 11:07:36'),
(646, 1, 'lifetech_obj_foreign_record', '//foreign record is used to use a particular key to fetch a value from the records\n//the table_labelvalue is what is will return, while the table_key is the key index to access each record\n\n$parameter_foreign = \"\'table_name= #Enter Your Table Name#\', \'table_labelvalue=compHead . qrtName \', \'table_key=department_id\'\";\n$get_foreign_feedback= lifetech_obj_foreign_record($parameter_foreign);\n$index_to_fetch=\'12384726\';\necho $get_foreign_feedback ->$index_to_fetch;', 'Lifefunction', NULL, '2024-10-26 11:07:36'),
(652, 1, 'lifetech_obj_db_schema($tableName)', '//the table schema is used to display all fieldnames in a table\r\n\r\n$table_name = \'#Enter Your Table Name#\';\r\necho lifetech_obj_db_schema($table_name);', 'Lifefunction', NULL, '2024-10-26 11:07:36'),
(710, 1, 'lifetech_obj_db_browse($tableName)', '//the table browse function is used to display all fieldnames and data in a table Format\r\n\r\n$table_name = \'#Enter Your Table Name#\';\r\necho lifetech_obj_db_browse($table_name);', 'Lifefunction', NULL, '2024-10-26 11:07:36'),
(715, 1, 'lifetech_obj_hyperlink($parameter)', '//this function is to diplay an hyperlink for the users\r\n$parameter_hyper = \"\'title=#enter your link titel#\', \'module_name=#Enter the Module Name of the link#\',\'content_name=#Enter the Content Name #\',\'caption=#Enter link Caption#\',\'get_value=#*Enter the GET value for the link#\',\'target=#*Enter the target#\',\'server_root=#*Enter the link Http Address#\',  \";\r\n$response_obj_hyper= lifetech_obj_hyperlink($parameter_hyper);\r\necho $response_obj_hyper;\r\n', 'Lifefunction', NULL, '2024-10-26 11:07:36'),
(718, 1, 'Controller GET', '//this is used to determine if the request from the frontend is GET method and to execute the codes\n//ob_end_clean is used to flush existing output and exit() is used to terminate and return to frontend code\n\nif(Controller::get(\'userRegSubmit\')){\n    ob_end_clean();\n     //write code here\n   exit();\n}\n\n/*\n //if the get parameter has value then you will use two parameter instead of ne \nif(Controller::get(\'userRegSubmit\', \'Submitted\')){\n    ob_end_clean();\n     //write code here\n   exit();\n}\n*/', 'Model_and_Controller', NULL, '2024-11-28 14:51:53'),
(721, 1, 'lifetech_obj_url_encrypt()', '//This is a function that u supply your ID and it return matching PIN and KEY that u can use to know if the ID is tampered on the URL Address\r\n        $load_obj_url_encrypt = getLifetechClass();\r\n          $load_obj_url_encrypt -> lifetech_general_id =  \'#Enter the Unique Value U want to genrate Pin and Key for\'; \r\n          $load_obj_url_encrypt -> lifetech_obj_url_encrypt();\r\n            $Url_Pin  = $load_obj_url_encrypt -> urlpin;  \r\n            $Url_Key = $load_obj_url_encrypt -> urlkey;   ', 'Lifefunction', NULL, '2024-10-26 11:07:36'),
(722, 1, 'Controller PostAND', '//this is when your are determining when two parameters is validated before executing a controller\r\n//ob_end_clean is used to flush existing output and exit() is used to terminate and return to frontend code\r\n\r\n//PHP syntax is if($_POST[\'userRegSubmit\']==\"Submitted\" && $_POST[\'api_key_status\']==\"Yes\")\r\n //if the get parameter has value then you will use two parameter instead of ne \r\nif(Controller::postAnd(\'userRegSubmit\', \'Submitted\')->get(\'api_key_status\',\'Yes\')){\r\n    ob_end_clean();\r\n     //write code here\r\n   exit();\r\n} \r\n\r\n', 'Model_and_Controller', NULL, '2024-11-28 15:06:55'),
(726, 1, 'lifetech_obj_url_decrypt()', '//This is the function that decrypt the  ID , PIN and KEY to know if the ID is tampered on the URL Address\r\n$load_obj_url_decrypt = getLifetechClass(); \r\n$load_obj_url_decrypt -> lifetech_general_id = #The general ID u supplied to get the PIN and Key#; \r\n$load_obj_url_decrypt -> urlpin = $Url_Pin ; \r\n$load_obj_url_decrypt -> urlkey = $Url_Key; \r\n$load_obj_url_decrypt -> lifetech_obj_url_decrypt();\r\nif ( $load_obj_url_decrypt -> response == \'success\'){ \r\necho \'Your Pin is Correct\';\r\n}else{\r\n  echo \'Your Injectecd Your Pin \';  \r\n}', 'Lifefunction', NULL, '2024-10-26 11:07:36'),
(744, 1, 'Controller POST', '//this is used to determine if the request from the frontend is POST method and to execute the codes\r\n//ob_end_clean is used to flush existing output and exit() is used to terminate and return to frontend code\r\n\r\nif(Controller::post(\'userRegSubmit\')){\r\n    ob_end_clean();\r\n     //write code here\r\n   exit();\r\n}\r\n\r\n/*\r\n //if the post parameter has value then you will use two parameter instead of ne \r\nif(Controller::post(\'userRegSubmit\', \'Submitted\')){\r\n    ob_end_clean();\r\n     //write code here\r\n   exit();\r\n}\r\n*/', 'Model_and_Controller', NULL, '2024-11-28 14:51:53'),
(767, 1, 'Controller GetOR', '//this is when your are determining either one or two paramaters is validated before executing a controller\r\n//ob_end_clean is used to flush existing output and exit() is used to terminate and return to frontend code\r\n\r\n//PHP syntax is if($_POST[\'userRegSubmit\']==\"Submitted\" || $_POST[\'api_key_status\']==\"Yes\")\r\n //if the get parameter has value then you will use two parameter instead of ne \r\nif(Controller::getOr(\'userRegSubmit\', \'Submitted\')->get(\'api_key_status\',\'Yes\')){\r\n    ob_end_clean();\r\n     //write code here\r\n   exit();\r\n} \r\n\r\n', 'Model_and_Controller', NULL, '2024-11-28 15:06:55'),
(773, 1, 'Model Creation', '//this is the point you create a model of your database table name which must be extended by model class\n//DbTableName is the table model you are creating\n//function if class_exists is to check if the model has already been created so that it will not crash your application\n\n\nif (class_exists(\'DbTableName\')) {  \n}else{ \nclass DbTableName extends Model{}\n}\n', 'Model_and_Controller', NULL, '2024-11-28 14:51:53'),
(792, 1, 'Controller GetAND', '//this is when your are determining when two parameters is validated before executing a controller\r\n//ob_end_clean is used to flush existing output and exit() is used to terminate and return to frontend code\r\n\r\n//PHP syntax is if($_POST[\'userRegSubmit\']==\"Submitted\" && $_POST[\'api_key_status\']==\"Yes\")\r\n //if the get parameter has value then you will use two parameter instead of ne \r\nif(Controller::getAnd(\'userRegSubmit\', \'Submitted\')->get(\'api_key_status\',\'Yes\')){\r\n    ob_end_clean();\r\n     //write code here\r\n   exit();\r\n} \r\n\r\n', 'Model_and_Controller', NULL, '2024-11-28 15:06:55'),
(797, 1, 'Controller PostOR', '//this is when your are determining either one or two paramaters is validated before executing a controller\r\n//ob_end_clean is used to flush existing output and exit() is used to terminate and return to frontend code\r\n\r\n//PHP syntax is if($_POST[\'userRegSubmit\']==\"Submitted\" || $_POST[\'api_key_status\']==\"Yes\")\r\n //if the get parameter has value then you will use two parameter instead of ne \r\nif(Controller::postOr(\'userRegSubmit\', \'Submitted\')->get(\'api_key_status\',\'Yes\')){\r\n    ob_end_clean();\r\n     //write code here\r\n   exit();\r\n} \r\n\r\n', 'Model_and_Controller', NULL, '2024-11-28 15:06:55'),
(802, 1, 'lifetech_get_password($param)', '//This is a function that will get u the Salt and Encrypted Value of a given Password\r\n$password_value = \'#Enter Your Password Value#\';\r\n$response_password_value = lifetech_get_password($password_value);\r\n$password = $response_password_value ->lifetech_password;\r\n$salt =   $response_password_value ->salt;', NULL, NULL, '2024-10-26 11:07:36'),
(814, 1, 'lifetech_email_exist($param)', '//This function will check whether Your Email or Username Already Exist on Your Website\r\n$email_toCheck = \'#enter the email you want to Check#\';\r\n$response_email_toCheck = lifetech_email_exist($email_toCheck);\r\n\r\nif($response_email_toCheck[\'response\'] == \"Yes\"){\r\n    echo \'Your Email Already Exist\';\r\n}else{\r\n    echo \'Your Email is not Existing\';\r\n}\r\n', NULL, NULL, '2024-10-26 11:07:36'),
(822, 1, 'JLON Object RM with Data', '//JLON; Javascript Lifetech Object Notation, this Model is used to make a varriable, array and json data to an Object, for usage on LIFETECH \n// We have JLON CREATE, JLON ENCODE and JLON DECODE.\n\n//1. JLON CREATE is when you are making a varriable an instance of an OBject for particular Usage\n$object_name jlon_create(\'#Enter Object Name#\');\n//once your object name is created , then u can be assigning properties to it anyhowe.g;\n$object_name -> surname = \'My surname\';\n//also you can retrieve or read value from you Object Model\n$staff_surname = $object_name -> surname ;\n\n//2. JLON ENCODE is when you want to convert existing array value or json data to JLON object\n$my_array_value = array(\"username\"=>\'ad01\',\"firstname\"=>\'ademide\'\"surname\"=>\'akinde\');\n $my_obj_staff = jlon_encode($my_array_value);\n//automatically your array has converted to the object Model, which can also be sent to other Prog Lang as JSON file\n\n\n\n//3. JLON DECODE is when you want to get value from the encoded JLON object, then u will decode before u can access it\n$decode_my_obj_staff = jlon_decode($$my_obj_staff)\n//automatically your object Model has decode to the object Usage, you can now be calling on the properties\necho $decode_my_obj_staff -> surname;', 'JLON', NULL, '2024-10-26 11:07:36'),
(905, 1, 'JLON Model to Interact With Database', '//This Abstraction model get data from the database and render it to the view template in order not to be goin to the DB everytime\r\n//we have JLON CREATE , JLON PROCESS, JLON READ, JLON WRITE, INDEXOF, and HEADEROF\r\n//1. JLON CREATE , to create the object name\r\n$object_name = jlon_create(\'object_name\');\r\n\r\n//2. JLON PROCESS is gettin all your table data to and object to u can call on\r\n//Note: the object name in JLON process must be same thing in Jlon create, and u are going to use it all through\r\n$parameter_jlon_process = \"\'table_name=#Enter Table name#\',   \'object_key=lifetech_general_id\', \'fieldname=site_name, address2 \',  \'object_name= #Enter Object Name#\'\";\r\n$jlon_process_jlon_lifetech_site_table = jlon_process($parameter_jlon_process);\r\n\r\n//3. JLON READ , when u want to read a value from the OBJECT Model of jLON, U will need the Record ID and fieldName   \r\n$surname =  $object_name ->jlon_read($record_id,$fieldName);\r\n\r\n//4. JLON WRITE , when u want to write back to the ORM, U will need RecordID, fieldName and Value to write\r\n$object_name-> jlon_write($record_id, $fieldName, $Value);\r\n\r\n//5. INDEXOF, this will tell you all the record ID in the Object Model\r\n$index_of_ID = indexof(\'#Enter ObjetName#\');\r\nforeach($index_of_ID as $index_of_value){\r\n    echo $index_of_value;\r\n}\r\n\r\n//6. HEADEROF, this function will tell you all header in the Object Model\r\n$header_of_ID = indexof(\'#Enter ObjetName#\');\r\nforeach($header_of_ID as $header_of_value){\r\n    echo $header_of_value;\r\n}', 'JLON', NULL, '2024-10-26 11:07:36'),
(909, 1, ' If statement', '\n{% if($username== \"You\"):  %}\n <div>\n  this is my name {! $username  !}\n </div>\n{% else: %}\n <div>\n  this is my other name {! $username  !}\n </div>\n{% endif;  %}', 'LifeRazor', NULL, '2024-11-28 16:29:33'),
(930, 1, 'while statement', '{% counter = 2; %}\r\n{% while($counter < 5):  %}\r\n   <div>\r\n    No: {! $counter !}\r\n  </div>\r\n{% counter ++ %}\r\n{%.  endwhile: %}', 'LifeRazor', NULL, '2024-11-28 16:33:38'),
(955, 1, 'foreach statement', '\r\n\r\n{% foreach($studentRecords as $students):  %}\r\n  <div>email: {! $students->email !}\r\n  </div>\r\n{%.  endforeach;  %}', 'LifeRazor', NULL, '2024-11-28 16:33:38'),
(992, 1, 'LifeRazor Print', '// variable in liferazor start with $ sign\r\n\r\n{! \"hell World!!\" !}\r\n\r\n// {! $username !}', 'LifeRazor', NULL, '2024-11-28 16:29:33'),
(1001, 1, 'Select', '// to load all your table records\r\n//Select * from tbl_name;\r\n$user->get()\r\n\r\n//to load based on parameters \r\n$user->select()->where(‘a’ , ’=’ , ’b’)-> orderby(‘username’)->limit(5)->get();\r\n\r\n/*if you want to view the sql statement just change the last chain to tosql\r\n$user->select()->where(‘a’ , ’=’ , ’b’)-> orderby(‘username’)->limit(5)->tosql();\r\n*/', 'MapLite', NULL, '2024-11-28 16:48:36'),
(1007, 1, 'findId', '//is automatically to find where the value is in lifetech_general_id\r\n\r\n$user->findId(‘1425’);\r\n//SQL syntax: Select * from tbl_name WHERE lifetech_general_id=’1425’;  \r\n', 'Maplite', NULL, '2024-11-28 16:48:36'),
(1028, 1, 'Insert', '$user = new TableName;\r\n$user->firsname =\"AKINDE\";\r\n$user->gender=\"MALE\";\r\n$user->save();\r\n\r\n//SQL SYNTAX: INSERT INTO tbl_name (username)VALUES(:username)', 'MapLite', NULL, '2024-11-28 16:57:18'),
(1032, 1, 'UPDATE', '$user = new TableName;\n$user->firsname =\"AKINDE\";\n$user->gender=\"MALE\";\n$user->update();\n\n/*OR\n$user->edit()->set()->where(‘firsname’, ‘=’, $firsname)->update();\n*/', 'MapLite', NULL, '2024-11-28 16:57:18'),
(1045, 1, 'DELETE', '$user = new TableName;\r\n$user->lifetech_general_id=\"9271948\";\r\n\r\n$user->delete();\r\n\r\n/*OR\r\n$users -> delete(‘username’, ‘LIKE’ , ‘$username’);\r\n*/', 'Maplite', NULL, '2024-11-28 17:01:56'),
(3000, 1, 'Lifetech All in One General functions', ' <?=lifetech_general_id(); ?>\r\n <?=lifetech_module_path(); ?>\r\n <?=lifetech_ses_role();?>\r\n <?=lifetech_uid(); ?>\r\n <?=lifetech_urid(); ?>\r\n <?=lifetech_theme_sitename(); ?>\r\n <?=lifetech_theme_subtitle(); ?>\r\n <?=lifetech_theme_address(); ?>\r\n <?=lifetech_theme_address2(); ?>\r\n <?=lifetech_theme_email(); ?>\r\n <?=lifetech_theme_email2(); ?>\r\n <?=lifetech_theme_phone(); ?>\r\n <?=lifetech_theme_phone2(); ?>\r\n <?=lifetech_theme_instagram(); ?>\r\n <?=lifetech_theme_facebook(); ?>\r\n <?=lifetech_theme_twitter(); ?>\r\n <?=lifetech_theme_linkedin(); ?>\r\n <?=lifetech_theme_open_hour(); ?>\r\n <?=lifetech_theme_closed_hour(); ?>\r\n <?=lifetech_theme_databasename(); ?>\r\n <?=lifetech_theme_path(); ?>', 'JLON', NULL, '2024-10-26 11:07:36');

